// Read-only measurement and bounded recommendations. No lead writes or publishing authority.
function growthParse(row){try{return JSON.parse(row?.payload||'{}');}catch{return {};}}
function growthDay(iso){return new Date(iso).toLocaleDateString('en-CA',{timeZone:'Europe/Paris'});}
function growthMetrics(leads,queue,clients,journal,now){
 if(![leads,queue,clients,journal].every(Array.isArray)||!Number.isFinite(Date.parse(now)))throw new Error('GROWTH_INVALID_SNAPSHOT');
 const unique=rows=>{const seen=new Map();return rows.filter(r=>{if(r.id===undefined)return true;const key=String(r.id),value=JSON.stringify(r);if(seen.has(key)){if(seen.get(key)!==value)throw new Error('GROWTH_INCONSISTENT_DUPLICATE_ROW');return false;}seen.set(key,value);return true;});};leads=unique(leads);queue=unique(queue);clients=unique(clients);journal=unique(journal);
 const day=growthDay(now),date=String(now).slice(0,10),receiptIds=new Set(),accepted=[];
 const inspect=(r,fallback)=>{if(r?.smtp_accepted!==true||!r.message_id||!/^250\b/.test(r.smtp_response||''))return;const ts=r.recorded_at_utc||r.accepted_at||fallback;if(!ts||growthDay(ts)!==day||r.report===true||receiptIds.has(r.message_id))return;receiptIds.add(r.message_id);accepted.push(r.message_id);};
 for(const row of queue){const p=growthParse(row);if(row.type==='commercial_campaign')for(const r of p.receipts||[])inspect(r,p.campaign_completed_at_utc);if(row.type==='action'&&p.smtp_receipt)inspect(p.smtp_receipt,row.last_action);}
 const prospects=queue.filter(r=>r.type==='prospect'),eligible=prospects.filter(r=>r.status==='approved'&&['HOT','WARM','HIGH'].includes(r.priority));
 const sourced=leads.filter(l=>l.createdAt&&Number.isFinite(Date.parse(l.createdAt))&&growthDay(l.createdAt)===day),statusCounts={};for(const l of leads)statusCounts[l.statut||'unknown']=(statusCounts[l.statut||'unknown']||0)+1;
 const hotIds=[...new Set(eligible.filter(r=>r.priority==='HOT').map(r=>{const p=growthParse(r);return Number(p.lead_id??leads.find(l=>String(l.email||'').toLowerCase()===String(p.email||'').toLowerCase())?.id);}).filter(id=>{const l=leads.find(l=>Number(l.id)===id);return Number.isFinite(id)&&id!==79&&l?.statut==='nouveau'&&!l.date_envoi&&!l.date_relance&&!l.date_reponse&&!l.message_id;}))];
 const positive=queue.filter(r=>r.type==='inbound_sales'&&growthParse(r).human_reply_verified===true&&growthParse(r).sentiment==='positive');
 const counts=kind=>queue.filter(r=>r.type===kind&&growthParse(r).execution_proof?.verified===true).length;
 const contentStates={};for(const row of queue.filter(r=>r.type==='content'))contentStates[row.status]=(contentStates[row.status]||0)+1;
 const publications=queue.filter(r=>r.type==='publication'),pub={};for(const r of publications)pub[r.status]=(pub[r.status]||0)+1;
 const externalSchedule=queue.filter(r=>r.type==='publication_observation').map(r=>({provider_post_id:growthParse(r).provider_post_id,state:'not_verified'}));
 const verifiedPosts=publications.filter(r=>{const p=growthParse(r);return p.platform_receipt?.verified===true&&p.platform_receipt?.post_id&&p.platform_receipt?.status==='published';});
 const errs=journal.filter(r=>String(r.date||r.createdAt||'').startsWith(date)&&/erreur|error|échec|failed|timeout/i.test(String(r.resultat)+' '+String(r.details))).length;
 const sources={};for(const l of sourced){let s='unattributed';try{s=new URL(l.source).hostname;}catch{if(['website','email','referral','W7'].includes(l.source))s=l.source;}sources[s]=(sources[s]||0)+1;}
 const windows=[0,7].map(offset=>{const end=Date.parse(now)-offset*86400000,start=end-7*86400000,types={};for(const l of leads){const t=Date.parse(l.createdAt);if(Number.isFinite(t)&&t>=start&&t<end)types[l.type||'unknown']=(types[l.type||'unknown']||0)+1;}return {days_before_now:offset,start_utc:new Date(start).toISOString(),end_utc:new Date(end).toISOString(),new_leads_by_type:types};});
 const journalEvidence={};for(const r of journal){const name=String(r.workflow||'').match(/^(W(?:10|[0-9])|Manager)\b/)?.[1];const ts=r.createdAt;if(name&&ts&&Number.isFinite(Date.parse(ts))&&(!journalEvidence[name]||ts>journalEvidence[name]))journalEvidence[name]=ts;}
 const blocked=queue.filter(r=>r.type==='integration'&&['needs_attention','blocked','uncertain'].includes(r.status)).map(r=>({task_key:r.task_key,status:r.status}));
 return {observed_at_utc:now,day_paris:day,source:'existing n8n tables; not provider API analytics',leads_total:leads.length,new_leads:sourced.length,lead_statuses:statusCounts,approved_prospect_rows:eligible.length,hot_lead_ids:hotIds,smtp_accepted_today_with_receipt:accepted.length,delivery_confirmed:null,replies_recorded:leads.filter(l=>!!l.date_reponse).length,positive_human_replies_verified:positive.length,site_visits_with_proof:counts('site_visit'),quotes_with_proof:counts('quote'),signed_contracts_with_proof:counts('contract'),crm_clients:clients.length,source_attribution:sources,content_queue_states:contentStates,weekly_comparison:windows,publication_queue_states:pub,external_schedule_observations:externalSchedule,provider_verified_published_posts:verifiedPosts.length,platform_inventory_verification:'unavailable_without_connected_read_credential',journal_errors_today:errs,journal_latest_evidence:journalEvidence,blocked_integrations:blocked,api_spend:null,api_spend_note:'No connected billing data; amounts unknown',observed_tokens:null};
